=== FILE: apb_regs.v ===
// apb_regs: four 32-bit read/write registers behind an APB4 completer port.
// Implements interface_spec.md per microarchitecture.md (zero wait states,
// no state machine, PSLVERR for unmapped addresses, synchronous active-low
// reset).
`default_nettype none

module apb_regs #(
    parameter integer ADDR_WIDTH = 8,
    parameter integer DATA_WIDTH = 32
) (
    input  wire                    pclk,
    input  wire                    presetn,
    input  wire [ADDR_WIDTH-1:0]   paddr,
    input  wire                    psel,
    input  wire                    penable,
    input  wire                    pwrite,
    input  wire [DATA_WIDTH-1:0]   pwdata,
    input  wire [DATA_WIDTH/8-1:0] pstrb,
    output reg  [DATA_WIDTH-1:0]   prdata,
    output wire                    pready,
    output wire                    pslverr
);

    localparam integer NBYTES = DATA_WIDTH / 8;

    // merge(old, data, strb): copy each byte of data whose strobe is set,
    // keep the other bytes of old.
    function [DATA_WIDTH-1:0] merge;
        input [DATA_WIDTH-1:0] old_val;
        input [DATA_WIDTH-1:0] new_val;
        input [NBYTES-1:0]     strb;
        integer b;
        begin
            merge = old_val;
            for (b = 0; b < NBYTES; b = b + 1) begin
                if (strb[b]) begin
                    merge[8*b +: 8] = new_val[8*b +: 8];
                end
            end
        end
    endfunction

    // The one cycle in which a transfer completes (pready is always high).
    wire       access = psel && penable;

    // is_mapped: word aligned and inside 0x0..0xC.
    wire       mapped = (paddr[1:0] == 2'b00) &&
                        (paddr[ADDR_WIDTH-1:4] == {(ADDR_WIDTH-4){1'b0}});

    wire [1:0] idx    = paddr[3:2];
    wire       wr_en  = access && pwrite && mapped;

    reg  [DATA_WIDTH-1:0] reg0_q;
    reg  [DATA_WIDTH-1:0] reg1_q;
    reg  [DATA_WIDTH-1:0] reg2_q;
    reg  [DATA_WIDTH-1:0] reg3_q;

    // Combinational 4:1 multiplexer of the registers, by idx.
    reg  [DATA_WIDTH-1:0] sel_val;

    always @* begin
        case (idx)
            2'd0:    sel_val = reg0_q;
            2'd1:    sel_val = reg1_q;
            2'd2:    sel_val = reg2_q;
            default: sel_val = reg3_q;
        endcase
    end

    wire [DATA_WIDTH-1:0] wr_merged = merge(sel_val, pwdata, pstrb);

    wire [DATA_WIDTH-1:0] reg0_d = (wr_en && (idx == 2'd0)) ? wr_merged : reg0_q;
    wire [DATA_WIDTH-1:0] reg1_d = (wr_en && (idx == 2'd1)) ? wr_merged : reg1_q;
    wire [DATA_WIDTH-1:0] reg2_d = (wr_en && (idx == 2'd2)) ? wr_merged : reg2_q;
    wire [DATA_WIDTH-1:0] reg3_d = (wr_en && (idx == 2'd3)) ? wr_merged : reg3_q;

    // Register file: reset value, else next state.
    always @(posedge pclk) begin
        if (!presetn) begin
            reg0_q <= {DATA_WIDTH{1'b0}};
            reg1_q <= {DATA_WIDTH{1'b0}};
            reg2_q <= {DATA_WIDTH{1'b0}};
            reg3_q <= {DATA_WIDTH{1'b0}};
        end else begin
            reg0_q <= reg0_d;
            reg1_q <= reg1_d;
            reg2_q <= reg2_d;
            reg3_q <= reg3_d;
        end
    end

    // Read data: zero unless this is a mapped read access.
    always @* begin
        prdata = {DATA_WIDTH{1'b0}};
        if (access && !pwrite && mapped) begin
            prdata = sel_val;
        end
    end

    assign pready  = 1'b1;
    assign pslverr = access && !mapped;

`ifdef FORMAL
    // Design-intent properties (microarchitecture section 6). The decode and
    // the byte check below are written independently of mapped and merge.
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge pclk) f_past_valid <= 1'b1;

    wire                    f_access = psel && penable;
    wire                    f_mapped = (paddr[1:0] == 2'b00) && (paddr < 16);
    wire [4*DATA_WIDTH-1:0] f_regs   = {reg3_q, reg2_q, reg1_q, reg0_q};

    // Manager assumptions: reset first, no transfer in reset, setup then
    // access, stable request through access, penable only after setup.
    always @(*) begin
        if (!f_past_valid) assume(!presetn);
        if (!presetn)      assume(!psel);
        if (penable)       assume(psel);
    end

    always @(posedge pclk) begin
        if (f_past_valid) begin
            if (penable) assume($past(psel && !penable));
            if ($past(psel && penable)) assume(!penable);
            if (presetn && $past(presetn) && $past(psel && !penable)) begin
                assume(psel && penable);
                assume(paddr  == $past(paddr));
                assume(pwrite == $past(pwrite));
                assume(pwdata == $past(pwdata));
                assume(pstrb  == $past(pstrb));
            end
        end
    end

    // Responses.
    always @(*) begin
        assert(pready);
        if (!f_access) begin
            assert(prdata == {DATA_WIDTH{1'b0}});
            assert(!pslverr);
        end else begin
            assert(pslverr == !f_mapped);
            if (pwrite || !f_mapped)
                assert(prdata == {DATA_WIDTH{1'b0}});
            else
                assert(prdata == f_regs[paddr[3:2]*DATA_WIDTH +: DATA_WIDTH]);
        end
    end

    // Registers are zero after reset.
    always @(posedge pclk) begin
        if (f_past_valid && !$past(presetn))
            assert(f_regs == {(4*DATA_WIDTH){1'b0}});
    end

    // Each byte changes only in a mapped write access to its register with
    // its strobe set, to the written byte.
    genvar fr, fb;
    generate
        for (fr = 0; fr < 4; fr = fr + 1) begin : g_f_reg
            for (fb = 0; fb < NBYTES; fb = fb + 1) begin : g_f_byte
                always @(posedge pclk) begin
                    if (f_past_valid && $past(presetn)) begin
                        if ($past(f_access && pwrite && f_mapped &&
                                  (paddr[3:2] == fr) && pstrb[fb]))
                            assert(f_regs[fr*DATA_WIDTH + 8*fb +: 8] ==
                                   $past(pwdata[8*fb +: 8]));
                        else
                            assert(f_regs[fr*DATA_WIDTH + 8*fb +: 8] ==
                                   $past(f_regs[fr*DATA_WIDTH + 8*fb +: 8]));
                    end
                end
            end
            always @(posedge pclk) begin
                if (f_past_valid && presetn)
                    cover(f_access && !pwrite && f_mapped &&
                          (paddr[3:2] == fr) &&
                          (prdata != {DATA_WIDTH{1'b0}}));
            end
        end
    endgenerate

    always @(posedge pclk) begin
        if (f_past_valid && presetn) begin
            cover(f_access && pwrite && !f_mapped);
            cover(f_access && !pwrite && !f_mapped);
        end
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
=== FILE: apb_regs_tb.v ===
// apb_regs_tb: directed and pseudo-random self-checking testbench for
// apb_regs. Inputs are driven after the falling edge and outputs sampled
// before the rising edge.
`default_nettype none

module apb_regs_tb;

    localparam integer AW = 8;
    localparam integer DW = 32;
    localparam integer SW = DW / 8;

    reg           pclk;
    reg           presetn;
    reg  [AW-1:0] paddr;
    reg           psel;
    reg           penable;
    reg           pwrite;
    reg  [DW-1:0] pwdata;
    reg  [SW-1:0] pstrb;
    wire [DW-1:0] prdata;
    wire          pready;
    wire          pslverr;

    apb_regs #(.ADDR_WIDTH(AW), .DATA_WIDTH(DW)) dut (
        .pclk    (pclk),
        .presetn (presetn),
        .paddr   (paddr),
        .psel    (psel),
        .penable (penable),
        .pwrite  (pwrite),
        .pwdata  (pwdata),
        .pstrb   (pstrb),
        .prdata  (prdata),
        .pready  (pready),
        .pslverr (pslverr)
    );

    integer         passed;
    integer         failed;
    integer         i;
    integer         k;
    reg             finished;
    reg [8*64-1:0]  nonce;
    reg [31:0]      rng;
    reg [DW-1:0]    model [0:3];

    reg [AW-1:0]    r_addr;
    reg [DW-1:0]    r_data;
    reg [SW-1:0]    r_strb;
    reg             r_op;
    reg             r_gap;

    initial pclk = 1'b0;
    always #5 pclk = ~pclk;

    // Reference decode: word aligned and below 0x10.
    function tb_mapped;
        input [AW-1:0] a;
        begin
            tb_mapped = (a[1:0] == 2'b00) && (a < 8'h10);
        end
    endfunction

    // Reference strobe merge, by byte mask.
    function [DW-1:0] tb_apply_strobe;
        input [DW-1:0] old_val;
        input [DW-1:0] new_val;
        input [SW-1:0] s;
        reg   [DW-1:0] mask;
        begin
            mask = {{8{s[3]}}, {8{s[2]}}, {8{s[1]}}, {8{s[0]}}};
            tb_apply_strobe = (old_val & ~mask) | (new_val & mask);
        end
    endfunction

    task next_rng;
        begin
            rng = rng ^ (rng << 13);
            rng = rng ^ (rng >> 17);
            rng = rng ^ (rng << 5);
        end
    endtask

    task check_bit;
        input            got;
        input            exp;
        input [8*64-1:0] what;
        begin
            if (got === exp) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("FAIL %0s: got %b expected %b (paddr 0x%h, time %0t)",
                       what, got, exp, paddr, $time);
            end
        end
    endtask

    task check_word;
        input [DW-1:0]   got;
        input [DW-1:0]   exp;
        input [8*64-1:0] what;
        begin
            if (got === exp) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("FAIL %0s: got 0x%h expected 0x%h (paddr 0x%h, time %0t)",
                       what, got, exp, paddr, $time);
            end
        end
    endtask

    task check_quiet;
        input [8*64-1:0] where;
        begin
            check_bit(pslverr, 1'b0, where);
            check_word(prdata, {DW{1'b0}}, where);
        end
    endtask

    // One idle cycle with random, ignored request signals.
    task idle;
        begin
            @(negedge pclk);
            psel    = 1'b0;
            penable = 1'b0;
            pwrite  = rng[0];
            paddr   = rng[15:8];
            pwdata  = rng;
            pstrb   = rng[7:4];
            next_rng;
            #1;
            check_quiet("quiet prdata/pslverr in idle");
        end
    endtask

    task apb_write;
        input [AW-1:0] a;
        input [DW-1:0] d;
        input [SW-1:0] s;
        reg            exp_err;
        begin
            exp_err = !tb_mapped(a);
            // Setup phase.
            @(negedge pclk);
            psel    = 1'b1;
            penable = 1'b0;
            pwrite  = 1'b1;
            paddr   = a;
            pwdata  = d;
            pstrb   = s;
            #1;
            check_quiet("quiet prdata/pslverr in write setup");
            // Access phase.
            @(negedge pclk);
            penable = 1'b1;
            #1;
            check_bit(pready, 1'b1, "pready high in write access (zero wait)");
            check_bit(pslverr, exp_err, "pslverr in write access");
            check_word(prdata, {DW{1'b0}}, "prdata zero in write access");
            if (!exp_err) begin
                model[a[3:2]] = tb_apply_strobe(model[a[3:2]], d, s);
            end
        end
    endtask

    task apb_read;
        input [AW-1:0] a;
        reg            exp_err;
        reg [DW-1:0]   exp_d;
        begin
            exp_err = !tb_mapped(a);
            exp_d   = exp_err ? {DW{1'b0}} : model[a[3:2]];
            // Setup phase.
            @(negedge pclk);
            psel    = 1'b1;
            penable = 1'b0;
            pwrite  = 1'b0;
            paddr   = a;
            pwdata  = rng;
            pstrb   = {SW{1'b0}};
            next_rng;
            #1;
            check_quiet("quiet prdata/pslverr in read setup");
            // Access phase.
            @(negedge pclk);
            penable = 1'b1;
            #1;
            check_bit(pready, 1'b1, "pready high in read access (zero wait)");
            check_bit(pslverr, exp_err, "pslverr in read access");
            check_word(prdata, exp_d, "prdata in read access");
        end
    endtask

    task read_all;
        integer n;
        begin
            for (n = 0; n < 4; n = n + 1) begin
                apb_read({n[5:0], 2'b00});
            end
        end
    endtask

    task do_reset;
        input integer cycles;
        integer n;
        begin
            for (n = 0; n < cycles; n = n + 1) begin
                @(negedge pclk);
                presetn = 1'b0;
                psel    = 1'b0;
                penable = 1'b0;
                #1;
                check_quiet("quiet prdata/pslverr in reset");
            end
            @(negedge pclk);
            presetn = 1'b1;
            psel    = 1'b0;
            penable = 1'b0;
            for (n = 0; n < 4; n = n + 1) begin
                model[n] = {DW{1'b0}};
            end
            #1;
            check_quiet("quiet prdata/pslverr after reset release");
        end
    endtask

    task finish_run;
        begin
            if (!finished) begin
                finished = 1'b1;
                if (!$value$plusargs("nirmaan_nonce=%s", nonce)) begin
                    nonce = {8*64{1'b0}};
                end
                $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
                $finish;
            end
        end
    endtask

    initial begin
        passed   = 0;
        failed   = 0;
        finished = 1'b0;
        nonce    = {8*64{1'b0}};
        rng      = 32'h2545_F491;
        presetn  = 1'b0;
        psel     = 1'b0;
        penable  = 1'b0;
        pwrite   = 1'b0;
        paddr    = {AW{1'b0}};
        pwdata   = {DW{1'b0}};
        pstrb    = {SW{1'b0}};
        for (k = 0; k < 4; k = k + 1) begin
            model[k] = {DW{1'b0}};
        end

        // 1. Reset values.
        do_reset(3);
        read_all;
        idle;

        // 2. Write then read every register, with idle gaps.
        apb_write(8'h00, 32'hA5A5_0000, 4'hF); idle; apb_read(8'h00); idle; idle;
        apb_write(8'h04, 32'h5A5A_1111, 4'hF); idle; apb_read(8'h04); idle;
        apb_write(8'h08, 32'hDEAD_BEEF, 4'hF); idle; idle; idle; apb_read(8'h08); idle;
        apb_write(8'h0C, 32'h0123_4567, 4'hF); idle; apb_read(8'h0C); idle;
        read_all;
        idle;

        // 3. Back-to-back transfers (setup right after an access).
        apb_write(8'h00, 32'h1111_1111, 4'hF);
        apb_write(8'h04, 32'h2222_2222, 4'hF);
        apb_read(8'h00);
        apb_write(8'h08, 32'h3333_3333, 4'hF);
        apb_read(8'h04);
        apb_read(8'h08);
        apb_write(8'h0C, 32'h4444_4444, 4'hF);
        apb_read(8'h0C);
        apb_write(8'h0C, 32'hFFFF_FFFF, 4'hF);
        apb_read(8'h0C);
        read_all;
        idle;

        // 4. Every strobe pattern (including none) on every register.
        for (k = 0; k < 4; k = k + 1) begin
            for (i = 0; i < 16; i = i + 1) begin
                apb_write({k[5:0], 2'b00}, 32'h8899_AABB, 4'hF);
                r_data = {4{i[7:0]}} ^ 32'hC3A5_5A3C;
                apb_write({k[5:0], 2'b00}, r_data, i[3:0]);
                apb_read({k[5:0], 2'b00});
            end
            idle;
        end
        read_all;
        idle;

        // 5a. Misaligned addresses inside the register range.
        for (i = 0; i < 16; i = i + 1) begin
            if (i[1:0] != 2'b00) begin
                apb_write(i[7:0], 32'hBAD0_0000 | i, 4'hF);
                apb_read(i[7:0]);
            end
        end
        read_all;
        idle;

        // 5b. Out-of-range addresses, including aliases of 0x0..0xC.
        for (i = 16; i < 256; i = i + 4) begin
            apb_write(i[7:0], 32'hE000_0000 | i, 4'hF);
            apb_read(i[7:0]);
        end
        apb_write(8'hFF, 32'h5555_AAAA, 4'hF);
        apb_read(8'hFF);
        apb_write(8'h11, 32'h7777_7777, 4'hF);
        apb_read(8'h13);
        apb_write(8'h10, 32'hFFFF_FFFF, 4'h0);
        read_all;
        idle;

        // 5c. Unmapped and mapped transfers back to back.
        apb_write(8'h20, 32'h0BAD_0BAD, 4'hF);
        apb_read(8'h00);
        apb_read(8'h21);
        apb_write(8'h04, 32'h600D_600D, 4'hF);
        apb_read(8'h04);
        apb_write(8'h00, 32'h0000_FFFF, 4'h0);
        apb_read(8'h00);
        idle;

        // 6. Pseudo-random traffic against the model.
        for (i = 0; i < 400; i = i + 1) begin
            next_rng;
            if (rng[2:0] == 3'b000) begin
                r_addr = rng[15:8];
            end else begin
                r_addr = {4'b0000, rng[9:8], 2'b00};
            end
            r_strb = rng[19:16];
            r_op   = rng[20];
            r_gap  = rng[21] & rng[22];
            next_rng;
            r_data = rng;
            if (r_op) begin
                apb_write(r_addr, r_data, r_strb);
            end else begin
                apb_read(r_addr);
            end
            if (r_gap) begin
                idle;
            end
        end
        read_all;
        idle;

        // 7. Reset again, from non-zero contents.
        apb_write(8'h00, 32'hFEED_0000, 4'hF);
        apb_write(8'h04, 32'hFEED_0004, 4'hF);
        apb_write(8'h08, 32'hFEED_0008, 4'hF);
        apb_write(8'h0C, 32'hFEED_000C, 4'hF);
        read_all;
        idle;
        do_reset(2);
        read_all;
        apb_write(8'h04, 32'hCAFE_F00D, 4'hF);
        apb_read(8'h04);
        read_all;
        idle;
        idle;

        finish_run;
    end

    // Watchdog: a hang is a failed run.
    initial begin
        #2000000;
        failed = failed + 1;
        $error("FAIL watchdog: testbench did not finish");
        finish_run;
    end

endmodule

